INSERT INTO `products` (`id`, `name`, `slug`, `added_by`, `user_id`, `brand_id`, `category_id`, `subcategory_id`, `thumbnail`, `photos`, `tags`, `description`, `short_description`, `status`, `is_published`, `is_cat`, `is_featured`, `unit`, `barcode`, `num_of_sale`, `video_link`, `is_variant`, `badge_name`, `batch_no`, `todays_deal`, `best_selling`, `position`, `is_new_arrival`, `stock_request`, `created_at`, `updated_at`) VALUES
(3192, '3D Hourglass 7 Color RGB Table Lamp Deep Sea Sandscape', '3d-hourglass-7-color-rgb-table-lamp-deep-sea-sandscape-1782204702-2552', 1, 1, NULL, 48, NULL, '142', NULL, NULL, '<p><strong>Product Name : 3D Hourglass 7 Color RGB Table Lamp Deep Sea Sandscape&nbsp;</strong></p>\n\n<p><strong>Description:&nbsp; &nbsp;&nbsp;</strong>Featuring a flowing 3D sand painting design and with 3&nbsp;color adjustable lights, this ornamental table lamp not only creates a cozy atmosphere but also relieves the fatigue of a day&#39;s study/work and relieves stress, giving you a comfortable experience.<br />\nWhat this sand table lamp with exquisite workmanship can offer you is that it is perfect as a gift for parents, children, colleagues and friends.<br />\nIt is constructed of glass material.&nbsp;It is suitable for living rooms, offices, hotels,&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; <strong><em>The total height of the night light is 20cm. The bottom diameter is 10cm, and the lampshade diameter is 16cm.</em></strong></p>\n\n<p>🚦<strong>Item Name : </strong>Sand Painting Lamp<br />\n🚦<strong>Material :</strong> Glass<br />\n🚦<strong>Light Source :</strong> Seven Colours<br />\n🚦<strong>Switch :</strong> Touch Switch<br />\n🚦<strong>Socket :</strong> USB<br />\n🚦<strong>Area :</strong> 5-8 Square Metres<br />\n🚦<strong>Two Charging Modes :</strong> USB Charging(Included), 3 x AA Batteries (Not Included)<br />\n🚦<strong>Features :</strong> 3-color Light Adjustable, 3D Sand Painting, High Translucency</p>\n\n<p><strong>Size Details :</strong><br />\n🚦Height: 20cm/7.87&quot;(Approx.)<br />\n🚦Bottom Diameter: 10cm/3.94&quot;(Approx.)<br />\n🚦Lampshade Diameter: 16cm/6.3&quot; (Approx.)</p>\n\n<p><img src=\"https://ae01.alicdn.com/kf/Sc177b9343a8f4795b6944d2f202417c6w.jpg\" /><img src=\"https://ae01.alicdn.com/kf/S60f1c300a8394e7cb9c56da4ba7bf6f9Q.jpg\" /><img src=\"https://ae01.alicdn.com/kf/S4bb9c07114cf44df96ad0178e1ecdbdcl.jpg\" /><img src=\"https://ae01.alicdn.com/kf/Sd9e8700c01dd459a9f2ae5864ac1c4358.jpg\" /></p>\n\n<p>&nbsp;</p>\n\n<p>&nbsp;</p>\n\n<p>&nbsp;</p>\n\n<p>&nbsp;</p>', 'The total height of the night light is 20cm. The bottom diameter is 10cm, and the lampshade diameter is 16cm.', 1, 1, 0, 0, 'Pc', '', 0, '', 0, '', 1, 0.00, 0, 1, 1, 0, '2026-06-23 08:51:42', '2026-06-23 08:51:42'),
(3193, 'Portable Air Conditioner Fan 500 Ml Water Tank USB Personal Cooler', 'portable-air-conditioner-fan-500-ml-water-tank-usb-personal-cooler-1782204703-7919', 1, 1, NULL, 50, NULL, '143', NULL, NULL, '<p><strong>Not Rechargeable&nbsp;</strong></p>\n\n<ul>\n	<li>Weight : 685g (without water)</li>\n	<li>Power : 10W Max</li>\n	<li>Voltage : 5V</li>\n	<li>Electric Current : 2A Max</li>\n	<li>Blowing Distance : 2.5m Max</li>\n	<li>Plug : Type-C USB Plug</li>\n	<li>Max Water Filled : 600ml</li>\n	<li>Volume Of Mist : 225ml / h Max</li>\n</ul>', '', 0, 1, 0, 0, 'Pc', '', 0, '', 0, '', 1, 0.00, 0, 2, 1, 0, '2026-06-23 08:51:43', '2026-06-23 08:51:43'),
(3194, 'Rechargeable Rain Cloud Humidifier Mushroom Lamp', 'rechargeable-rain-cloud-humidifier-mushroom-lamp-1782204703-1456', 1, 1, NULL, 48, NULL, '144', NULL, NULL, '<ul>\n	<li>A Humidifier Can Rain: Have you ever seen a humidifier that makes it rain? The cute humidifier features a rain cloud design, which relieves dryness while showing scenes of rain, making you feel like you are in nature and helping you relax.</li>\n	<li>7 Colors Night Light: The rain cloud humidifier diffuser has 7 unique colors. The night light creates a quiet and warm environment, running smoothly and without noise, perfect for you to breathe and sleep better and relax.</li>\n	<li>Easy to Use: Press the left button to adjust the LED light color, and the middle button is the on/off button, you can also adjust the water size, and press the right button to adjust the LED light brightness.</li>\n	<li>Wide Usage: The multifunctional cloud humidifier is a good helper to relieve pressure and a sleep aid for your family. Its unique design makes it a great addition to any room, providing both function and relaxation. You can use it in your living room, bedroom, office or anywhere you need to add a relaxing touch.</li>\n	<li>IMPROVES YOUR SLEEP QUALITY: Natural sounds are also like Mother Nature&rsquo;s version of a white noise machine. Get yourself a good night of rest by using DHYANUT Rain Cloud Humidifier to your nightstand. For extra relaxation, add 5-10 drops of an essential oil that helps promote sleep (like lavender, or rosemary)!</li>\n	<li>AROMA DIFFUSER: This rain cloud humidifier Air Freshner is also an essential oil diffuser, you can add essential oils according to your needs, through the collision of water droplets to stimulate the emanation of essential oils, improve the quality of airflow and enjoy a good night&#39;s sleep.</li>\n</ul>', '', 1, 1, 0, 0, 'Pc', '', 0, '', 0, '', 1, 0.00, 0, 3, 1, 0, '2026-06-23 08:51:43', '2026-06-23 08:51:43'),
(3195, '3D Hourglass Deep Sea Sandscape', '3d-hourglass-deep-sea-sandscape-1782204703-8969', 1, 1, NULL, 48, NULL, '145', NULL, NULL, '<p>&bull; Sand Photo Material: Deep sea sand photo with lead-free, transparent glass and durable, eco-friendly ABS stand.<br />\n&bull; 3D Vivid Sand Image: Dynamic 3D sand image combined with 5-color fine and rough sand, so that the whole sand image is more versatile and vivid than others.<br />\n&bull; Relaxing sand toys: When the sand flows slowly and the natural sand landscape is seen, you will be more relaxed and peaceful. Great sand picture toys for kids and adults.<br />\n&bull; Sand art decoration: 3D sand flowing art creates a classic, relaxing and peaceful atmosphere, great for home and office decoration. This unique moving sand art with exquisite packaging, perfect for birthday gifts, Christmas gifts, New Year gifts.<br />\n&bull; With air regulator: Equipped with an air regulator, you can flexibly adjust the air and flow rate of sand painting.<br />\n&bull; Great packaging for floating sand paintings perfect for giving as gifts. Sand art is a special thing, it is different from ordinary gifts, your family or friends will be surprised. The versatile sand art painting not only has artistic value, but can also be used as a relaxation tool.</p>', '', 1, 1, 0, 0, 'Pc', '', 0, '', 0, '', 1, 0.00, 0, 4, 1, 0, '2026-06-23 08:51:43', '2026-06-23 08:51:43'),
