(3543, 'Silver Crest Stainless Steel Body Electric Mini Grinder 1500W (Germany Technology)', 'silver-crest-stainless-steel-body-electric-mini-grinder-1500w-(germany-technology)-1782204827-5733', 1, 1, NULL, 50, NULL, '497', NULL, NULL, '<p>High-Power 1500W Electric Grinder &ndash; Fast, Efficient, and Reliable</p>\n\n<p>Experience effortless grinding with our 1500W high-power motor, designed to handle spices, nuts, grains, and more in just 30 seconds to 1 minute. Made with food-grade stainless steel, the cup is safe, durable, and rust-resistant, ensuring long-lasting performance.</p>\n\n<p>Compact and lightweight, this grinder is perfect for daily home use, while the push-start control offers simple one-touch operation. Thanks to German technology, it delivers reliable performance every time.</p>\n\n<p>Ideal for dry spices, coffee, rice, black cumin, lentils, and other ingredients, it&rsquo;s perfect for preparing small batches quickly. Cleaning is a breeze with the smooth stainless steel surface, making maintenance hassle-free.</p>\n\n<p>Upgrade your kitchen with this multi-purpose, high-performance grinder, built for speed, convenience, and durability.</p>', 'High-Power 1500W Electric Grinder – Fast, Efficient, and Reliable\n\nExperience effortless grinding with our 1500W high-power motor, designed to handle spices, nuts, grains, and more in just 30 seconds to 1 minute. Made with food-grade stainless steel, the cup is safe, durable, and rust-resistant, ensuring long-lasting performance.\n\nCompact and lightweight, this grinder is perfect for daily home use, while the push-start control offers simple one-touch operation. Thanks to German technology, it delivers reliable performance every time.\n\nIdeal for dry spices, coffee, rice, black cumin, lentils, and other ingredients, it’s perfect for preparing small batches quickly. Cleaning is a breeze with the smooth stainless steel surface, making maintenance hassle-free.\n\nUpgrade your kitchen with this multi-purpose, high-performance grinder, built for speed, convenience, and durability.', 1, 1, 0, 0, 'Pc', '', 0, '', 0, '', 1, 0.00, 0, 1169, 0, 0, '2026-06-23 08:53:47', '2026-06-23 08:53:47'),
(3544, 'Rechargeable Desktop Fan With Hook Wall Mounted - IW8038-M', 'rechargeable-desktop-fan-with-hook-wall-mounted---iw8038-m-1782204827-8760', 1, 1, NULL, 50, NULL, '498', NULL, NULL, '<h2>Product details</h2>\n\n<p><strong>Iwin Rechargeable Desktop Fan</strong>&nbsp;(Model: IW8038-M) designed for portability and versatility.&nbsp;</p>\n\n<p>&nbsp;</p>\n\n<ul>\n	<li><strong>Battery &amp; Charging:</strong>&nbsp;Features a 3.7V 4000mAh lithium battery with 5V/1A fast charging capability.&nbsp;</li>\n</ul>\n\n<p>&nbsp;</p>\n\n<ul>\n	<li><strong>Performance:</strong>&nbsp;Utilizes a brushless motor for strong wind output.&nbsp;</li>\n</ul>\n\n<p>&nbsp;</p>\n\n<ul>\n	<li><strong>Features:</strong>&nbsp;Includes a digital display with touch control for 5 adjustable speeds.&nbsp;</li>\n</ul>\n\n<p>&nbsp;</p>\n\n<ul>\n	<li><strong>Versatility:</strong>&nbsp;Designed with a 360-degree rotation feature, and can be used on a desk, hung by a hook, or mounted on a wall.&nbsp;</li>\n</ul>\n\n<h2>Specifications</h2>\n\n<h2>Key Features</h2>\n\n<p><strong>Iwin Rechargeable Desktop Fan</strong>&nbsp;(Model: IW8038-M) designed for portability and versatility.&nbsp;</p>\n\n<p>&nbsp;</p>\n\n<ul>\n	<li><strong>Battery &amp; Charging:</strong>&nbsp;Features a 3.7V 4000mAh lithium battery with 5V/1A fast charging capability.&nbsp;</li>\n</ul>\n\n<p>&nbsp;</p>\n\n<ul>\n	<li><strong>Performance:</strong>&nbsp;Utilizes a brushless motor for strong wind output.&nbsp;</li>\n</ul>\n\n<p>&nbsp;</p>\n\n<ul>\n	<li><strong>Features:</strong>&nbsp;Includes a digital display with touch control for 5 adjustable speeds.&nbsp;</li>\n</ul>\n\n<p>&nbsp;</p>\n\n<ul>\n	<li><strong>Versatility:</strong>&nbsp;Designed with a 360-degree rotation feature, and can be used on a desk, hung by a hook, or mounted on a wall.&nbsp;</li>\n</ul>\n\n<h2>What&rsquo;s in the box</h2>\n\n<p>IWIN FAN</p>\n\n<h2>Specifications</h2>\n\n<ul>\n	<li>SKU: IW047HA6PQPDBNAFAMZ</li>\n	<li>Weight (kg): 0.5</li>\n	<li>Color: N/A</li>\n	<li>Main Material: N/A</li>\n</ul>', 'IW8038-M-Rechargeable-Desktop-Fan-With-Hook-Wall-Mounted-Optional', 1, 1, 0, 0, 'Pc', '', 0, '', 0, '', 1, 0.00, 0, 1170, 0, 0, '2026-06-23 08:53:47', '2026-06-23 08:53:47'),
(3545, '🔥 High Speed Livo Turbo Fan LV-2600-0002', '🔥-high-speed-livo-turbo-fan-lv-2600-0002-1782204827-1594', 1, 1, NULL, 52, NULL, '499', NULL, NULL, '<p>&nbsp;High Speed Livo Turbo Fan LV-2600 &ndash; Powerful Cooling, Maximum Comfort</p>\n\n<p>Stay cool and comfortable even in the hottest weather with the Livo Turbo Fan LV-2600. Designed for high performance and durability, this fan delivers powerful airflow with energy efficiency&mdash;perfect for homes, offices, shops, and commercial spaces.</p>\n\n<p>⚡ Key Features:</p>\n\n<p>✅ High-Speed Performance<br />\nEquipped with a powerful motor that ensures strong and consistent airflow, keeping your room cool within minutes.</p>\n\n<p>✅ Turbo Air Technology<br />\nAdvanced turbo blade design enhances air circulation, providing wider coverage and faster cooling.</p>\n\n<p>✅ Durable Build Quality<br />\nMade with high-quality materials to ensure long-lasting performance and reliability.</p>\n\n<p>✅ Energy Efficient<br />\nConsumes less electricity while delivering maximum output&mdash;helping you save on your electricity bills.</p>\n\n<p>✅ Adjustable Speed Control<br />\nMultiple speed settings allow you to customise airflow according to your comfort.</p>\n\n<p>✅ Low Noise Operation<br />\nEnjoy a peaceful environment with minimal noise, ideal for sleeping or working.</p>\n\n<p>🏠 Ideal For:<br />\nHome &amp; Bedroom<br />\nOffice &amp; Workspace<br />\nShops &amp; Small Businesses<br />\nStudy Rooms</p>', '', 1, 1, 0, 0, 'Pc', '', 0, '', 0, '', 1, 0.00, 0, 1171, 0, 0, '2026-06-23 08:53:47', '2026-06-23 08:53:47'),
(3546, '🔥 High Speed Livo Turbo Fan LV-2600-0001', '🔥-high-speed-livo-turbo-fan-lv-2600-0001-1782204827-3816', 1, 1, NULL, 52, NULL, '500', NULL, NULL, '<p>&nbsp;</p>\n\n<p>&nbsp;High Speed Livo Turbo Fan LV-2600 &ndash; Powerful Cooling, Maximum Comfort</p>\n\n<p>Stay cool and comfortable even in the hottest weather with the Livo Turbo Fan LV-2600. Designed for high performance and durability, this fan delivers powerful airflow with energy efficiency&mdash;perfect for homes, offices, shops, and commercial spaces.</p>\n\n<p>⚡ Key Features:</p>\n\n<p>✅ High-Speed Performance<br />\nEquipped with a powerful motor that ensures strong and consistent airflow, keeping your room cool within minutes.</p>\n\n<p>✅ Turbo Air Technology<br />\nAdvanced turbo blade design enhances air circulation, providing wider coverage and faster cooling.</p>\n\n<p>✅ Durable Build Quality<br />\nMade with high-quality materials to ensure long-lasting performance and reliability.</p>\n\n<p>✅ Energy Efficient<br />\nConsumes less electricity while delivering maximum output&mdash;helping you save on your electricity bills.</p>\n\n<p>✅ Adjustable Speed Control<br />\nMultiple speed settings allow you to customise airflow according to your comfort.</p>\n\n<p>✅ Low Noise Operation<br />\nEnjoy a peaceful environment with minimal noise, ideal for sleeping or working.</p>\n\n<p>🏠 Ideal For:<br />\nHome &amp; Bedroom<br />\nOffice &amp; Workspace<br />\nShops &amp; Small Businesses<br />\nStudy Rooms</p>', '', 1, 1, 0, 0, 'Pc', '', 0, '', 0, '', 1, 0.00, 0, 1172, 0, 0, '2026-06-23 08:53:47', '2026-06-23 08:53:47');
